  let heldStageWaitObserved = false;
  let heldStageProbeError = null;
  let stageSettledBeforeRelease = true;
  let mutationSettledBeforeRelease = false;
  let heldStageDuring = null;
  let heldStageReadError = null;
  let heldStageReleased = false;
  try {
    const heldStageWaitDeadline = performance.now() + 10_000;
    while (!heldStageSettled && performance.now() < heldStageWaitDeadline) {
      const hold = await evalIn('window.__CF_SLICE__.api.state().persistence.hold');
      if (hold === 'protected-payload') {
        heldStageWaitObserved = true;
        break;
      }
      await sleep(25);
    }
    heldMutationPromise = evalIn('window.__CF_SLICE__.api.__smokePersistNow()').then(
      (value) => { heldMutationSettled = true; return value; },
      (error) => {
        heldMutationSettled = true;
        heldMutationError = String(error instanceof Error ? error.message : error);
        return null;
      },
    );
    const heldMutationDeadline = performance.now() + 10_000;
    while (!heldMutationSettled && !heldStageSettled
      && performance.now() < heldMutationDeadline) await sleep(25);
    heldStageDuring = await evalIn(READ_STORED_V4_STAGE_EXPRESSION);
    stageSettledBeforeRelease = heldStageSettled;
    mutationSettledBeforeRelease = heldMutationSettled;
  } catch (error) {
    heldStageProbeError = String(error instanceof Error ? error.message : error);
    heldStageReadError = heldStageDuring === null ? heldStageProbeError : null;
  }
  finally {
    heldStageReleased = await evalIn('window.__CF_SLICE__.api.__smokeReleaseImportRace()') === true;
  }
  const [heldStageAccepted, heldMutationResult] = await Promise.all([
    heldStagePromise, heldMutationPromise,
  ]);
  const heldWriterWitness = await evalIn(
    'window.__CF_SLICE__.api.state().persistence.importRace',
  );
  const heldStageObserved = await evalIn(READ_STORED_V4_STAGE_EXPRESSION);
  const heldStageControl = {
    armed: heldStageArmed,
    stageWaitObserved: heldStageWaitObserved,
    stageSettledBeforeRelease,
    mutationSettledBeforeRelease,
    mutationResult: heldMutationResult,
    sameBytesBeforeRelease: JSON.stringify(heldStageDuring) === JSON.stringify(heldFixtureBefore),
    released: heldStageReleased,
    writerWitness: heldWriterWitness,
    accepted: heldStageAccepted,
    observed: heldStageObserved,
    expected: ONE_BAD_FIELD_V4_RAW,
    backup: STALE_AUTOSAVE_RAW,
  };
  if (!heldStoredV4StageOutcome(heldStageControl)) {
    throw new Error('SAVED ROUTE STAGING CONTROL did not join/block/atomically stage across the held persist: '
      + JSON.stringify({
        ...heldStageControl,
        heldStageProbeError,
        observed: {
          primary: describeStoredValue(heldStageObserved?.primary),
          backup: describeStoredValue(heldStageObserved?.backup),
        },
        before: {
          primary: describeStoredValue(heldFixtureBefore?.primary),
          backup: describeStoredValue(heldFixtureBefore?.backup),
        },
        during: {
          primary: describeStoredValue(heldStageDuring?.primary),
          backup: describeStoredValue(heldStageDuring?.backup),
        },
        heldStageDocumentToken, heldStageReceipt, heldStageAssessment,
        heldStageError, heldMutationError, heldStageReadError,
      }));
  }
  await requireStoredV4Stage(
    sess, evalIn, OUTER_AUTH_SAVED_ROUTE_RAW, 'SAVED ROUTE AUTHORIZATION', undefined,
    { allowedHolds: ['protected-payload'] },
  );
  await navigateToSlice(sess, URL0, 'source-valid saved route beyond saved reach');
  await sleep(2200);
  const outerAuthBoot = await evalIn(`window.__CF_SLICE__.api.state()`);
  const outerAuthBootOutcome = (state) => state.mode === 'universe'
    && state.gal === null && state.star === null && state.planet === null
    && state.save.savedView === null && state.save.viewType === null
    && state.save.name === importedExplorerName(SAVED_AUTH_EXPLORER_NAME) && state.save.essence === 4321
    && JSON.stringify(state.save.landed) === JSON.stringify(CANONICAL_VETERAN_LANDED)
    && state.save.customNames.some(([key, name]) => key === 'p133' && name === 'Homeworld')
    && state.save.ascCh === 2 && Object.keys(state.save.primeFill).length === 0
    && state.codexCount === 3 && state.atlasCount === 4 && state.atlasTravelable === 2;
  if (!outerAuthBootOutcome(outerAuthBoot)) {
    fails.push('SAVED ROUTE AUTHORIZATION: source-valid outer location did not fall back to Cosmos/NAV_HOME with unrelated ledger intact: '
      + JSON.stringify(outerAuthBoot));
  }
  requireRenderedSceneMatch('SAVED ROUTE AUTHORIZATION FALLBACK', outerAuthBoot);
  if (outerAuthBootOutcome({ ...outerAuthBoot, mode: 'galaxy', gal: OUTER_REACH_GALAXY.seed })
    || outerAuthBootOutcome({
      ...outerAuthBoot, save: { ...outerAuthBoot.save, essence: 0 },
    })) {
    fails.push('SAVED ROUTE AUTHORIZATION CONTROL FAILED — injected unauthorized navigation/progress loss stayed green');
  }
  await evalIn(`window.__CF_SLICE__.api.__smokePersistNow()`);
  const outerAuthRepairedRaw = JSON.parse(await evalIn(READ_PRIMARY_EXPRESSION));
  if (outerAuthRepairedRaw.view !== null
    || outerAuthRepairedRaw.me !== importedExplorerName(SAVED_AUTH_EXPLORER_NAME)
    || outerAuthRepairedRaw.essence !== 4321 || Number(outerAuthRepairedRaw.asc) !== 2
    || Object.keys(outerAuthRepairedRaw.prime || {}).length !== 0
    || !Array.isArray(outerAuthRepairedRaw.log)
    || !outerAuthRepairedRaw.log.some((row) => row?.id === 'outer-galaxy')
    || JSON.stringify(outerAuthRepairedRaw.land) !== JSON.stringify(CANONICAL_VETERAN_LANDED)) {
    fails.push('SAVED ROUTE AUTHORIZATION: persisted repair changed more than the view/normal export projection: '
      + JSON.stringify(outerAuthRepairedRaw));
  }
  await evalIn(`document.getElementById('railatlas')?.click()`);
  const outerAtlasSetup = {
    target: await evalIn(atlasTravelTargetExpression('outer-galaxy')),
    before: await evalIn(`window.__CF_SLICE__.api.state()`),
  };
  const outerAtlasTargetAssessment = assessAtlasTravelTarget(outerAtlasSetup.target, {
    atlasId: 'outer-galaxy',
  });
  const outerAtlasRawBefore = await evalIn(READ_PRIMARY_EXPRESSION);
  let outerAtlasPointer = null;
  if (!outerAtlasTargetAssessment.ok) {
    fails.push('ATLAS AUTHORIZATION SETUP: source-proven outer route did not expose one enabled, settled native Travel action: '
      + JSON.stringify({ setup: outerAtlasSetup, assessment: outerAtlasTargetAssessment }));
  } else {
    await armDesktopPointerReceipt();
    await clickDesktopPoint({ x: outerAtlasSetup.target.travel.x, y: outerAtlasSetup.target.travel.y });
    outerAtlasPointer = await takeDesktopPointerReceipt();
  }
  await sleep(120);
  const outerAtlasAfter = await evalIn(`window.__CF_SLICE__.api.state()`);
  const outerAtlasRawAfter = await evalIn(READ_PRIMARY_EXPRESSION);
  const atlasAuthStableProjection = (state) => JSON.stringify({
    mode: state.mode, gal: state.gal, galX: state.galX, galY: state.galY,
    star: state.star, starX: state.starX, starY: state.starY,
    planet: state.planet, planetOrdinal: state.planetOrdinal,
    panelOpen: state.panelOpen, cardOpen: state.cardOpen, cardTitle: state.cardTitle,
    renderedScene: state.renderedScene, atlasCount: state.atlasCount, save: state.save,
  });
  const assessOuterAtlasAuthorization = ({ before, after, rawBefore, rawAfter, target, pointer }) => {
    const targetAssessment = assessAtlasTravelTarget(target, { atlasId: 'outer-galaxy' });
    const checks = {
      target: targetAssessment.ok,
      pointer: pointer?.trusted === true && pointer.pointerType === 'mouse'
        && pointer.atlasTravelId === 'outer-galaxy' && pointer.atlasRowId === 'outer-galaxy'
        && pointer.atlasActionTag === 'BUTTON'
        && Math.abs(pointer.x - target?.travel?.x) <= 0.75
        && Math.abs(pointer.y - target?.travel?.y) <= 0.75,
      state: atlasAuthStableProjection(after) === atlasAuthStableProjection(before),
      storage: rawAfter === rawBefore,
      boundary: after?.toastSerial > before?.toastSerial
        && String(after?.toastText || '').startsWith('⬆ Beyond Your Saved Reach')
        && !String(after?.toastText || '').includes('Beyond Your Charter'),
    };
    return { ok: Object.values(checks).every((value) => value === true), checks, targetAssessment };
  };
  const outerAtlasAuthorization = assessOuterAtlasAuthorization({
    before: outerAtlasSetup.before, after: outerAtlasAfter,
    rawBefore: outerAtlasRawBefore, rawAfter: outerAtlasRawAfter,
    target: outerAtlasSetup.target, pointer: outerAtlasPointer,
  });
  if (outerAtlasTargetAssessment.ok && !outerAtlasAuthorization.ok) {
    fails.push('ATLAS AUTHORIZATION: enabled outer route bypassed/closed navigation, changed ledger/storage, or missed its exact boundary: '
      + JSON.stringify({ before: outerAtlasSetup.before, after: outerAtlasAfter,
        rawStable: outerAtlasRawAfter === outerAtlasRawBefore, target: outerAtlasSetup.target,
        pointer: outerAtlasPointer, assessment: outerAtlasAuthorization }));
  }
  const atlasAuthBypassCtl = {
    ...outerAtlasAfter,
    mode: 'galaxy', gal: OUTER_REACH_GALAXY.seed,
    galX: OUTER_REACH_GALAXY.x, galY: OUTER_REACH_GALAXY.y,
    panelOpen: null,
  };
  if (outerAtlasAuthorization.ok) {
    const atlasAuthControl = (mutate) => {
      const candidate = structuredClone({
        before: outerAtlasSetup.before, after: outerAtlasAfter,
        rawBefore: outerAtlasRawBefore, rawAfter: outerAtlasRawAfter,
        target: outerAtlasSetup.target, pointer: outerAtlasPointer,
      });
      mutate(candidate);
      return assessOuterAtlasAuthorization(candidate);
    };
    const atlasAuthorizationControls = {
      directBypass: atlasAuthControl((candidate) => { candidate.after = atlasAuthBypassCtl; }),
      wrapperBecomesAction: atlasAuthControl((candidate) => {
        candidate.target.row.tag = 'BUTTON'; candidate.target.row.interactive = true;
      }),
      wrongTarget: atlasAuthControl((candidate) => { candidate.target.travel.id = 'p133'; }),
      unhitTarget: atlasAuthControl((candidate) => { candidate.target.travel.hit = false; }),
      wrongAction: atlasAuthControl((candidate) => { candidate.pointer.atlasTravelId = 'p133'; }),
      wrongRow: atlasAuthControl((candidate) => { candidate.pointer.atlasRowId = 'p133'; }),
      untrusted: atlasAuthControl((candidate) => { candidate.pointer.trusted = false; }),
      coordinateDrift: atlasAuthControl((candidate) => { candidate.pointer.x += 2; }),
      storageDrift: atlasAuthControl((candidate) => { candidate.rawAfter += ' '; }),
      missingBoundary: atlasAuthControl((candidate) => {
        candidate.after.toastSerial = candidate.before.toastSerial;
      }),
      wrongBoundary: atlasAuthControl((candidate) => {
        candidate.after.toastText = '⬆ Beyond Your Charter';
      }),
    };
    if (Object.values(atlasAuthorizationControls).some((control) => control.ok)) {
      fails.push('ATLAS AUTHORIZATION CONTROLS FAILED — a route bypass, wrong native target, storage drift, or boundary mutation stayed green: '
        + JSON.stringify(atlasAuthorizationControls));
    }
  }
  if (outerAtlasAfter.panelOpen === 'atlas') await closeDesktopPanel();

  /* 4b1. STORED-ROUTE FIELD REPAIR. A complete supported expedition with a
     stale same-seed galaxy coordinate must boot safely at Cosmos, repair only
     `view`, and preserve identity, progress, Atlas history, Charter, rewards,
     and names. This drives the raw IndexedDB ingress rather than an in-memory
     resolver probe. */
  await requireStoredV4Stage(
    sess, evalIn, STALE_SAVED_ROUTE_RAW, 'SAVED ROUTE FIELD REPAIR', undefined,
    { allowedHolds: [null] },
  );
  await navigateToSlice(sess, URL0, 'stale saved-route field-local fallback');
  await sleep(2200);
  const staleSavedBoot = await evalIn(`window.__CF_SLICE__.api.state()`);
  const staleSavedBootOutcome = (state) => state.mode === 'universe'
    && state.gal === null && state.star === null && state.planet === null
    && state.save.savedView === null && state.save.name === 'Field-local Route Repair'
    && state.save.essence === 4321
    && JSON.stringify(state.save.landed) === JSON.stringify(CANONICAL_VETERAN_LANDED)
    && state.save.customNames.some(([key, name]) => key === 'p133' && name === 'Homeworld')
    && state.save.ascCh === 2 && state.codexCount === 3 && state.atlasCount === 3;
  if (!staleSavedBootOutcome(staleSavedBoot)) {
    fails.push('SAVED ROUTE FIELD REPAIR: stale location did not fall back to Cosmos with unrelated progress intact: '
      + JSON.stringify(staleSavedBoot));
  }
  requireRenderedSceneMatch('SAVED ROUTE FIELD REPAIR', staleSavedBoot);
  if (staleSavedBootOutcome({ ...staleSavedBoot, mode: 'surface' })
    || staleSavedBootOutcome({
      ...staleSavedBoot, save: { ...staleSavedBoot.save, essence: 0 },
    })) {
    fails.push('SAVED ROUTE FIELD-REPAIR CONTROL FAILED — injected stale navigation/progress loss stayed green');
  }
  await evalIn(`window.__CF_SLICE__.api.__smokePersistNow()`);
  const repairedSavedRaw = await evalIn(READ_PRIMARY_EXPRESSION);
  let repairedSaved = null;
  try { repairedSaved = JSON.parse(repairedSavedRaw); } catch { /* finding below includes the raw failure */ }
  if (!repairedSaved || repairedSaved.view !== null || repairedSaved.me !== 'Field-local Route Repair'
    || repairedSaved.essence !== 4321 || !Array.isArray(repairedSaved.land)
    || JSON.stringify(repairedSaved.land) !== JSON.stringify(CANONICAL_VETERAN_LANDED)
    || !Array.isArray(repairedSaved.names)
    || !repairedSaved.names.some(([key, name]) => key === 'p133' && name === 'Homeworld')) {
    fails.push('SAVED ROUTE FIELD REPAIR: exact stored replacement did not isolate repair to `view`: '
      + JSON.stringify(repairedSaved));
  }

  /* 4c. GATE C's FRONT DOOR, rehearsed with the veteran fixture: the import
     sheet's own path (api.importBlob = the button's handler) must validate,
     store the veteran, and reboot into its name, stardust and view. Every
     rejected input below owns a before/after exact-primary assertion. */
  const vrRaw = INVENTORY_VETERAN_RAW;
  /* a garbage blob must be REFUSED with nothing stored */
  const preGarbageImportRaw = await evalIn(READ_PRIMARY_EXPRESSION);
  const refuse = await evalIn(`window.__CF_SLICE__.api.importBlob('{"not":"a save"' )`).catch(() => 'navigated');
  const postGarbageImportRaw = await evalIn(READ_PRIMARY_EXPRESSION);
  if (refuse === null || refuse === 'navigated' || postGarbageImportRaw !== preGarbageImportRaw) {
    fails.push('importBlob accepted garbage, reloaded, or changed exact primary bytes: '
      + JSON.stringify({ refuse, preserved: postGarbageImportRaw === preGarbageImportRaw }));
  }
  const preSparseImportRaw = postGarbageImportRaw;
  const refuseSparseV4 = await evalIn(`window.__CF_SLICE__.api.importBlob(${JSON.stringify(SPARSE_V4_RAW)})`).catch(() => 'navigated');
  const postSparseImportRaw = await evalIn(READ_PRIMARY_EXPRESSION);
  if (refuseSparseV4 === null || refuseSparseV4 === 'navigated' || postSparseImportRaw !== preSparseImportRaw) {
    fails.push('destructive import accepted or wrote sparse v4 lookalike: ' + JSON.stringify({ refuseSparseV4, preserved: postSparseImportRaw === preSparseImportRaw }));
  }
  const prePartialImportRaw = postSparseImportRaw;
  const refusePartialV4 = await evalIn(`window.__CF_SLICE__.api.importBlob(${JSON.stringify(PARTIAL_V4_RAW)})`).catch(() => 'navigated');
  const postPartialImportRaw = await evalIn(READ_PRIMARY_EXPRESSION);
  if (refusePartialV4 === null || refusePartialV4 === 'navigated' || postPartialImportRaw !== prePartialImportRaw) {
    fails.push('destructive import accepted or wrote plausible partial v4: ' + JSON.stringify({ refusePartialV4, preserved: postPartialImportRaw === prePartialImportRaw }));
  }
  const preFutureImportRaw = postPartialImportRaw;
  const refuseFuture = await evalIn(`window.__CF_SLICE__.api.importBlob(${JSON.stringify(FUTURE_V99_RAW)})`).catch(() => 'navigated');
  const postFutureImportRaw = await evalIn(READ_PRIMARY_EXPRESSION);
  if (refuseFuture === null || refuseFuture === 'navigated' || postFutureImportRaw !== preFutureImportRaw) {
    fails.push('destructive import accepted or wrote future-version bytes: '
      + JSON.stringify({ refuseFuture, preserved: postFutureImportRaw === preFutureImportRaw }));
  }

  /* Drive one valid import through the visible textarea/button with legal
     surrounding JSON whitespace. The live primary may use the checked,
     trimmed candidate, but the best-effort recovery keepsake promises the
     exact submitted textarea text. The injected trimmed-localStorage control
     proves this comparison rejects the defect that prompted the check. */
  const whitespaceImportRaw = ` \n${vrRaw}\n\t`;
  const whitespaceImportToken = await sliceToken(sess);
  const whitespaceImportStart = await evalIn(`(()=>{ document.getElementById('docksets')?.click();
    document.getElementById('setimport')?.click(); const input=document.getElementById('importtext'),go=document.getElementById('importgo');
    if(!(input instanceof HTMLTextAreaElement)||!(go instanceof HTMLButtonElement)) return {started:false,input:!!input,go:!!go};
    input.value=${JSON.stringify(whitespaceImportRaw)}; go.click(); return {started:true,length:input.value.length}; })()`);
  if (!whitespaceImportStart.started || whitespaceImportStart.length !== whitespaceImportRaw.length) {
    fails.push('IMPORT EXACT KEEPSAKE: visible valid-import path did not receive every textarea byte: '
      + JSON.stringify(whitespaceImportStart));
  }
  await waitForSlice(sess, 'desktop exact-keepsake whitespace import', { previousToken: whitespaceImportToken });
  await assertBootTickerRunning('post-import replacement boot');
  const whitespaceKeepsake = await evalIn(`(()=>{ const expected=${JSON.stringify(whitespaceImportRaw)};
    const actual=localStorage.getItem('cf_v2_import_original');
    return {exact:actual===expected,actualLength:actual?.length??null,expectedLength:expected.length,
      leading:actual?.slice(0,2)??null,trailing:actual?.slice(-2)??null}; })()`);
  if (!whitespaceKeepsake.exact) {
    fails.push('IMPORT EXACT KEEPSAKE: valid JSON surrounding whitespace was not retained byte-for-byte after reload: '
      + JSON.stringify(whitespaceKeepsake));
  }
  const whitespaceKeepsakeControl = await evalIn(`(()=>{ const key='cf_v2_import_original',expected=${JSON.stringify(whitespaceImportRaw)};
    const before=localStorage.getItem(key); localStorage.setItem(key,expected.trim());
    const acceptedTrimmed=localStorage.getItem(key)===expected;
    if(before===null)localStorage.removeItem(key);else localStorage.setItem(key,before);
    return {acceptedTrimmed,restored:localStorage.getItem(key)===before}; })()`);
  if (whitespaceKeepsakeControl.acceptedTrimmed || !whitespaceKeepsakeControl.restored) {
    fails.push('IMPORT EXACT KEEPSAKE CONTROL FAILED — injected trimmed storage was accepted or not restored: '
      + JSON.stringify(whitespaceKeepsakeControl));
  }

  /* F4 native evidence joins the published runtime diagnostics to the raw
     split player row, revision and immutable receipt store. This runs after
     the real import above so `current-v5` (not an in-memory fresh default) is
     the accepted boot. Pure predicate controls each falsify one required
     authority fact without mutating the live expedition. */
  const f4CurrentAuthority = await waitForF4Writable('F4 current authority', {
    previousToken: whitespaceImportToken,
  });
  const f4CurrentToken = f4CurrentAuthority.token;
  const f4ReadyState = f4CurrentAuthority.state;
  const f4ReadyRaw = f4CurrentAuthority.raw;
  const f4ReadyInput = {
    state: f4ReadyState, raw: f4ReadyRaw, token: f4CurrentToken, previousToken: whitespaceImportToken,
  };
  const f4ReadyAssessment = assessF4ReadyAuthority(f4ReadyInput);
  if (!f4ReadyAssessment.ok) {
    fails.push('F4 CURRENT AUTHORITY: ready diagnostics did not match durable raw IndexedDB authority: '
      + JSON.stringify({ assessment: f4ReadyAssessment, state: f4ReadyState.persistence, raw: f4ReadyRaw }));
  }
  const runtimeVariant = (fields) => ({
    ...f4ReadyState,
    persistence: {
      ...f4ReadyState.persistence,
      runtime: { ...f4ReadyState.persistence.runtime, ...fields },
    },
  });
  const persistenceVariant = (fields) => ({
    ...f4ReadyState,
    persistence: { ...f4ReadyState.persistence, ...fields },
  });
  const f4ReadyControls = [
    assessF4ReadyAuthority({ ...f4ReadyInput, state: { ...f4ReadyState, persistence: { ...f4ReadyState.persistence, bootKind: 'fresh-v5' } } }),
    assessF4ReadyAuthority({ ...f4ReadyInput, token: whitespaceImportToken }),
    assessF4ReadyAuthority({ ...f4ReadyInput, state: persistenceVariant({ seedBootstrapPending: true }) }),
    assessF4ReadyAuthority({ ...f4ReadyInput, state: persistenceVariant({ bootRouteRepairPending: true }) }),
    assessF4ReadyAuthority({ ...f4ReadyInput, state: persistenceVariant({ mutationBlocked: true }) }),
    assessF4ReadyAuthority({ ...f4ReadyInput, state: { ...f4ReadyState,
      sceneResources: { ...f4ReadyState.sceneResources, pendingPersistenceWrites: 1 } } }),
    assessF4ReadyAuthority({ ...f4ReadyInput, state: runtimeVariant({ leaseOwned: false }) }),
    assessF4ReadyAuthority({ ...f4ReadyInput, state: runtimeVariant({ answerable: false }) }),
    assessF4ReadyAuthority({ ...f4ReadyInput, state: runtimeVariant({ accruing: false }) }),
    assessF4ReadyAuthority({ ...f4ReadyInput, raw: { ...f4ReadyRaw, seed: (f4ReadyRaw.seed + 1) >>> 0 } }),
    assessF4ReadyAuthority({ ...f4ReadyInput, raw: { ...f4ReadyRaw, ordinal: f4ReadyRaw.ordinal + 1 } }),
    assessF4ReadyAuthority({ ...f4ReadyInput, raw: { ...f4ReadyRaw, revision: f4ReadyRaw.revision + 1 } }),
  ];
  if (f4ReadyControls.some((control) => control.ok)) {
    fails.push('F4 CURRENT AUTHORITY CONTROL FAILED — a false boot/token/seed/write/lease/readiness/accrual/raw parity predicate stayed green: '
      + JSON.stringify(f4ReadyControls));
  }

  const f4PersistBefore = { state: f4ReadyState, raw: f4ReadyRaw };
  const f4PersistResult = await evalIn(`window.__CF_SLICE__.api.__smokePersistNow()`);
  const f4Persisted = {
    result: f4PersistResult,
    state: await evalIn(`window.__CF_SLICE__.api.state()`),
    raw: await evalIn(READ_F4_AUTHORITY_EXPRESSION),
    token: f4CurrentToken,
  };
  await navigateToSlice(sess, URL0, 'F4 persistence reload');
  await assertBootTickerRunning('F4 persistence reload');
  const f4ReloadAuthority = await waitForF4Writable('F4 reloaded authority', {
    previousToken: f4CurrentToken,
  });
  const f4ReloadToken = f4ReloadAuthority.token;
  const f4Reloaded = {
    state: f4ReloadAuthority.state,
    raw: f4ReloadAuthority.raw,
    token: f4ReloadToken,
  };
  const f4PersistBundle = { before: f4PersistBefore, persisted: f4Persisted, reloaded: f4Reloaded };
  const f4PersistAssessment = assessF4PersistReload(f4PersistBundle);
  if (!f4PersistAssessment.ok) {
    fails.push('F4 PERSIST/RELOAD: seed, clock or exact explicit-persist revision evidence failed: '
      + JSON.stringify({ assessment: f4PersistAssessment, bundle: f4PersistBundle }));
  }
  const f4PersistControls = [
    assessF4PersistReload({ ...f4PersistBundle, persisted: { ...f4Persisted, raw: { ...f4Persisted.raw, revision: f4PersistBefore.raw.revision } } }),
    assessF4PersistReload({ ...f4PersistBundle, reloaded: { ...f4Reloaded, raw: { ...f4Reloaded.raw, seed: (f4PersistBefore.raw.seed + 1) >>> 0 } } }),
    assessF4PersistReload({ ...f4PersistBundle, persisted: { ...f4Persisted, raw: { ...f4Persisted.raw, activePlayMs: f4PersistBefore.raw.activePlayMs - 1 } } }),
    assessF4PersistReload({ ...f4PersistBundle, reloaded: { ...f4Reloaded,
      state: { ...f4Reloaded.state, persistence: { ...f4Reloaded.state.persistence,
        runtime: { ...f4Reloaded.state.persistence.runtime, commits: 1 },
        lastOutcome: `committed:${f4Reloaded.raw.revision}` } } } }),
    assessF4PersistReload({ ...f4PersistBundle, reloaded: { ...f4Reloaded,
      raw: { ...f4Reloaded.raw, activePlayMs: f4Reloaded.raw.activePlayMs + 1 } } }),
  ];
  if (f4PersistControls.some((control) => control.ok)) {
    fails.push('F4 PERSIST/RELOAD CONTROL FAILED — bad revision/seed/active-play evidence stayed green: '
      + JSON.stringify(f4PersistControls));
  }

  /* Seed a genuine old ordinal-zero receipt, arm a native replacement
     witness, and invoke the real validated import. The replacement boundary
     must reset receipts/RNG atomically. The fixture-owned progression oracle
     then selects either an empty current prefix or exactly one boot-catch-up
     Arc 9 receipt before Smoke appends the immediately following outcome. */
  const f4ReplacementToken = await sliceToken(sess);
  const f4ReplacementHeartbeatQuiescence = await evalIn(
    `window.__CF_SLICE__.api.__smokeQuiesceF4Heartbeat()`,
  );
  const f4ReplacementStartedAt = Date.now();
  const f4StageStarted = await evalIn(STAGE_OLD_F4_RECEIPT_EXPRESSION);
  const f4StagedRaw = await evalIn(READ_F4_AUTHORITY_EXPRESSION);
  const f4TraceArmed = await evalIn(ARM_F4_REPLACEMENT_TRACE_EXPRESSION);
